/**
 * Public, consent-gated phone capture for the Nightly sleep surface. Normalizes the number to E.164, records explicit consent, stores it as pending, and (idempotently) sends one opt-in confirmation iMessage. Re-submitting the same number on the same product never duplicates or re-spams.
 * @summary Capture a phone number opt-in for a consumer product
 */
export const SubscribePhoneBody = zod.object({
  phone: zod
    .string()
    .describe(
      "Phone number in any common format; normalized to E.164 server-side.",
    ),
  product: zod
    .enum(["nightly"])
    .describe("Which consumer product surface the number was captured on."),
  consent: zod
    .boolean()
    .describe("Must be true — explicit opt-in to receive texts."),
  source: zod
    .string()
    .nullish()
    .describe("Optional free-text capture-surface tag."),
});

export const SubscribePhoneResponse = zod.object({
  ok: zod.boolean(),
  pending: zod
    .boolean()
    .optional()
    .describe(
      "True when a confirmation text was (re)issued and confirmation is awaited.",
    ),
  alreadySubscribed: zod
    .boolean()
    .optional()
    .describe(
      "True when the number is already an active subscriber for this product.",
    ),
});

/**
 * Returns the caller's per-product notification channel preferences (email / imessage / both), the products they are entitled to, and the status of any phone number linked to their account. Scoped strictly to the cookie-resolved consumer; never exposes another account.
 * @summary Get the signed-in consumer's notification channel preferences
 */
export const GetNotificationSettingsResponse = zod.object({
  email: zod.string().describe("The account email (the email channel target)."),
  phone: zod.object({
    number: zod
      .string()
      .nullish()
      .describe(
        "The account's linked E.164 number, or null when none is linked.",
      ),
    status: zod
      .union([
        zod.literal("active"),
        zod.literal("pending"),
        zod.literal("opted_out"),
        zod.literal(null),
      ])
      .nullable()
      .describe(
        "active = confirmed and usable for iMessage; pending = confirmation awaited; opted_out = replied STOP; null = no number linked.\n",
      ),
  }),
  products: zod.array(
    zod.object({
      product: zod.enum(["nightly"]),
      channel: zod
        .enum(["email", "imessage", "both"])
        .describe("How a consumer is notified for a product."),
      subscribed: zod
        .boolean()
        .describe("Whether the caller is currently entitled to this product."),
    }),
  ),
});

